&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Utilize Sales CRM tools to track all pertinent account information and sales progress as well as&amp;nbsp;maintain&amp;nbsp;accurate&amp;nbsp;pipeline reporting in alignment with manager guidance to support forecasting accuracy.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559737&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
